  dict(q="When is an off-cycle payment appropriate?", o=["Any time an employee asks to be paid early","When a transaction failed to pay through no fault of the employee or HCM","For every new hire"], a=1, why="Off-cycle covers failures like an Oracle glitch, and the request must meet the form's criteria."),
  dict(q="Who runs the off-cycle (QuickPay) payment?", o=["The HCM","Payroll","The employee's manager"], a=1, why="Payroll runs QuickPay. You submit the transaction and the request, then tell payroll."),
