dict(slug="net-one-time-stipend", topic="payroll", topic_label="Compensation Management",
 title_pre="Process a net one-time", title_em="stipend", name="Process a net one-time stipend",
 system="Oracle HCM", time="6 min", sources=[BRIANA],
 intro=["Use this when the employee should take home a fixed amount, such as the $500 net at-home office stipend. You enter the net amount and Oracle works out the gross so the take-home matches.", TWO_PATHS],
 use_when="You are paying a fixed take-home amount.",
 steps=[
  {"t":"Start the transaction.","d":"Individual Compensation is where one-time and recurring payments outside salary are awarded.","sub":["Quick Actions > Individual Compensation > select the employee, or","Search the employee's name > Individual Compensation."]},
  {"t":"Click Add > One-time or recurring payment.","d":"This opens a new payment line for the employee."},
  {"t":"Plan: Lump sum payment.","d":"The plan decides which pay element is used and how it is taxed and reported. Lump sum is used for this kind of stipend."},
  {"t":"Start date: the first day of the target payroll month.","d":"For example, Nov 1 for the November check. A one-time payment pays in the payroll that covers this date."},
  {"t":"Enter the amount in the Net field (for example, $500).","d":"Net is what the employee takes home. Oracle grosses it up to cover taxes. Use Amount only when the figure is gross."},
  {"t":"Leave Process separately set to Yes.","d":"Oracle calculates the payment on its own (so supplemental tax rules can apply), then pays it in the same paycheck as regular pay. It does not create a separate check."},
  {"t":"Click Save.","d":"Saving keeps the line. It isn't submitted yet."},
  {"t":"Submit, or Continue to add comments or attachments first.","d":SUBMIT_D},
 ],
 watch=["Missed the cutoff (around the 18th)? Date it for next month.","Only change Process separately if payroll tells you to.","Pay goes to direct deposit, which is required."],
 docs=docs("icp","runtypes"),
 quiz=[
  dict(q="Which field do you use for a fixed take-home amount?", o=["Amount","Net","Gross"], a=1, why="Net is take-home. Amount is gross."),
  dict(q="You want the payment on the November check. What start date?", o=["Today","Nov 1","Nov 30"], a=1, why="Use the first day of the payroll month you're targeting."),
  dict(q="What does Process separately = Yes do?", o=["Issues a separate paper check","Calculates the payment on its own, then pays it with regular pay","Delays the payment a month"], a=1, why="It is calculated separately (for example, for supplemental tax) and paid in the same paycheck."),
 ]),

